print('\nmost divergent (sd):', [(r['id'], round(r['sd'], 2), r['lo'], r['hi']) for r in sorted(rows, key=lambda r: -r['sd'])[:6]])
print('self vs others:', [(r['id'], r['self'], round(r['mean_wo_self'], 1)) for r in rows if abs(r['self'] - r['mean_wo_self']) >= 1.5])
print('syntheses (self-scored):', {k: (n, sum(t)) for k, (n, t) in SYN.items()})
json.dump(rows, open(__file__.replace('.py', '.json'), 'w'), ensure_ascii=False, indent=1)
